# جمل v2 مالهاش وجود عند المتطوعين (سطور البصيرة الحكيمة، والرسالة القديمة بزرار التواصل، والافتتاح القديم)
DROP_PREFIXES = ['بعد آخر سطر في الافتتاح:', 'في آخر القسم، للتلات نسخ:', 'في آخر القسم، للحالات كلها:', 'مكان السطر الأخير:',
                 'في آخر القسم: «والنقطة', '[النسخة المنفردة] ولو الثقل', 'مكان سطر النسخة المنفردة:',
                 'التقرير ده خريطة لأيامك زي ما هي النهارده، مش حكم عليك. هو مبني على اللي اخترته إنت في المحطات السبعة']


def main():
    fp, npth = os.path.join(HERE, 'texts.fem.json'), os.path.join(HERE, 'texts.neutral.json')
    fem = json.load(open(fp, encoding='utf-8'))
    neu = json.load(open(npth, encoding='utf-8'))
    before = len(fem)
    fem = {k: v for k, v in fem.items() if not any(k.startswith(p) for p in DROP_PREFIXES)}
    dropped = before - len(fem)
    for k, v in FEM.items():
        if v is not None and v != k:
            fem[k] = v
    for k in NEUTRAL:
        if k not in neu:
            neu.append(k)
    json.dump(fem, open(fp, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    json.dump(neu, open(npth, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(f'texts.fem.json: {len(fem)} جملة (اتشال {dropped} من v2) · texts.neutral.json: {len(neu)}')


if __name__ == '__main__':
    main()
